   448→/**
   449→ * Stream an LLM endpoint into a new card, then re-enable action buttons.
   450→ * Enforces a maximum of 3 cards by removing the oldest collapsed card first.
   451→ */
   452→async function runCardStreamProcess(sourceText, endpoint, type, label) {
   453→    if (csIsStreaming) return;
   454→
   455→    // Cap at 3 total cards: remove oldest collapsed card if needed
   456→    const existingCards = Array.from(csCards.querySelectorAll('.cs-card'));
   457→    if (existingCards.length >= 3) {
   458→        const oldest = existingCards.find(c => !c.classList.contains('cs-expanded'));
   459→        if (oldest) csCards.removeChild(oldest);
   460→    }
   461→
   462→    // Disable all action buttons during streaming
   463→    csIsStreaming = true;
   464→    disableAllCardActions();
   465→
   466→    // Create a new card with empty text (will be streamed in)
   467→    const newCard   = buildCard({ type, label, text: ' ', meta: [] });
   468→    csCards.appendChild(newCard);
   469→    setupCardActionHandlers(newCard);
   470→
   471→    // Collapse all others, expand the new card
   472→    csCards.querySelectorAll('.cs-card.cs-expanded').forEach(c => {
   473→        c.classList.remove('cs-expanded');
   474→        c.querySelector('.cs-card-header').setAttribute('aria-expanded', 'false');
   475→    });
   476→    newCard.classList.add('cs-expanded');
   477→    newCard.querySelector('.cs-card-header').setAttribute('aria-expanded', 'true');
   478→    newCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
   479→
   480→    const textEl    = newCard.querySelector('.cs-card-text');
   481→    const previewEl = newCard.querySelector('.cs-card-preview');
   482→    textEl.textContent = '';
   483→    textEl.classList.add('cs-streaming');
   484→
   485→    let accumulated = '';
   486→
   487→    try {
   488→        const response = await fetch(`${getBackendBaseUrl()}${endpoint}`, {
   489→            method:  'POST',
   490→            headers: { 'Content-Type': 'application/json' },
   491→            body:    JSON.stringify({ text: sourceText }),
   492→        });
   493→
   494→        if (!response.ok) throw new Error(`HTTP ${response.status}`);
   495→
   496→        const reader  = response.body.getReader();
   497→        const decoder = new TextDecoder();
   498→
   499→        while (true) {
   500→            const { done, value } = await reader.read();
   501→            if (done) break;
   502→            // Abort if the card was removed (user navigated back)
   503→            if (!document.contains(newCard)) break;
   504→            accumulated += decoder.decode(value, { stream: true });
   505→            textEl.textContent = accumulated;
   506→            // Keep preview in sync while streaming
   507→            const streamWords = accumulated.trim().split(/\s+/).filter(Boolean);
   508→            previewEl.textContent = streamWords.slice(0, 15).join(' ') + (streamWords.length > 15 ? '…' : '');
   509→        }
   510→
   511→    } catch (err) {
   512→        console.error('Card stream error:', err);
   513→        if (document.contains(newCard)) {
   514→            textEl.textContent = 'Error: could not process. Check connection and try again.';
   515→        }
   516→    } finally {
   517→        if (document.contains(newCard)) {
   518→            textEl.classList.remove('cs-streaming');
   519→        }
   520→        csIsStreaming = false;
   521→        updateCardActionStates();
   522→    }
   523→}
