   551→/* ===== WEBHOOK SEND ===== */
   552→async function sendMessage(text, source) {
   553→    const webhookUrl = localStorage.getItem('webhookUrl') || '';
   554→    const timestamp  = new Date().toISOString();
   555→    const payload    = { text, source, timestamp };
   556→    const msgEl      = addMessage(text, timestamp, 'sending');
   557→
   558→    if (!webhookUrl) {
   559→        updateMessageStatus(msgEl, 'no-webhook');
   560→        return;
   561→    }
   562→
   563→    try {
   564→        const res = await fetch(webhookUrl, {
   565→            method:  'POST',
   566→            headers: { 'Content-Type': 'application/json' },
   567→            body:    JSON.stringify(payload),
   568→        });
   569→        if (!res.ok) throw new Error(`HTTP ${res.status}`);
   570→        updateMessageStatus(msgEl, 'sent');
   571→    } catch (err) {
   572→        console.warn('Webhook error:', err);
   573→        updateMessageStatus(msgEl, 'error');
   574→    }
   575→}
