   728→/* ===================================================
   729→   QUICK MODE — Web Speech API
   730→   No WebSocket. No backend. Browser-only.
   731→   =================================================== */
   732→
   733→const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
   734→
   735→function getRecognitionLang() {
   736→    return localStorage.getItem('recognitionLang') || navigator.language || 'en-US';
   737→}
   738→
   739→function initRecognition() {
   740→    if (!SpeechRecognition) return;
   741→
   742→    recognition = new SpeechRecognition();
   743→    recognition.continuous      = true;
   744→    recognition.interimResults  = true;
   745→    recognition.lang            = getRecognitionLang();
   746→    recognition.maxAlternatives = 1;
   747→
   748→    recognition.onstart = () => {
   749→        isListening      = true;
   750→        quickFinalTranscript = '';
   751→        showLiveTranscript('', 'quick');
   752→        quickBtn.classList.add('recording');
   753→        quickRing.classList.add('recording');
   754→        quickBtn.setAttribute('aria-pressed', 'true');
   755→        brainstormBtn.disabled = true;
   756→        replayButton.disabled  = true;
   757→        micHint.textContent = 'Listening… tap Quick to stop';
   758→        micHint.classList.add('active');
   759→        micHint.classList.remove('brainstorm-active', 'processing');
   760→    };
   761→
   762→    recognition.onresult = (event) => {
   763→        let interim = '';
   764→        for (let i = event.resultIndex; i < event.results.length; i++) {
   765→            const result = event.results[i];
   766→            if (result.isFinal) {
   767→                quickFinalTranscript += result[0].transcript + ' ';
   768→            } else {
   769→                interim += result[0].transcript;
   770→            }
   771→        }
   772→        const displayText = (quickFinalTranscript + interim).trim();
   773→        updateLiveText(displayText);
   774→        resetSilenceTimer();
   775→    };
   776→
   777→    recognition.onerror = (event) => {
   778→        if (event.error !== 'no-speech') {
   779→            console.warn('Speech recognition error:', event.error);
   780→        }
   781→        stopQuickMode();
   782→    };
   783→
   784→    recognition.onend = () => {
   785→        // If we didn't stop manually, recognition auto-stopped
   786→        if (isListening) {
   787→            finishQuickRecording();
   788→        }
   789→    };
   790→}
   791→
   792→function resetSilenceTimer() {
   793→    clearTimeout(silenceTimer);
   794→    silenceTimer = setTimeout(() => {
   795→        if (isListening) stopQuickMode();
   796→    }, SILENCE_DELAY);
   797→}
   798→
   799→function startQuickMode() {
   800→    if (isListening || isBrainstormRecording || isBrainstormProcessing || isReplaying) return;
   801→    if (!recognition) {
   802→        alert('Speech recognition is not available in this browser.');
   803→        return;
   804→    }
   805→    hideTranscriptBar();
   806→    // Stop any active local playback
   807→    if (isPlayingBack) stopLocalPlayback();
   808→    // Stop wake word listener if running (can't run both concurrently)
   809→    if (wakeWordListening) stopWakeWordListening();
   810→    try {
   811→        recognition.start();
   812→    } catch (e) {
   813→        console.warn('Could not start recognition:', e);
   814→        initRecognition();
   815→        try { recognition.start(); } catch (_) {}
   816→    }
   817→    resetSilenceTimer();
   818→}
   819→
   820→function stopQuickMode() {
   821→    clearTimeout(silenceTimer);
   822→    // Mark as not listening BEFORE calling recognition.stop() so that
   823→    // recognition.onend doesn't also call finishQuickRecording()
   824→    isListening = false;
   825→    if (recognition) {
   826→        try { recognition.stop(); } catch (_) {}
   827→    }
   828→    finishQuickRecording();
   829→}
