   831→function finishQuickRecording() {
   832→    isListening = false;
   833→    clearTimeout(silenceTimer);
   834→    quickBtn.classList.remove('recording');
   835→    quickRing.classList.remove('recording');
   836→    quickBtn.setAttribute('aria-pressed', 'false');
