   843→    const text = quickFinalTranscript.trim();
   844→    quickFinalTranscript = '';
   845→    if (text) {
   846→        showTranscriptBar(text, 'quick');
   847→    }
   848→
   849→    // Resume hands-free wake word listening
   850→    if (handsFreeEnabled) {
