   864→/* ===================================================
   865→   WAKE WORD DETECTION — always-on "Hey Chill" listener
   866→   =================================================== */
   867→
   868→function matchesWakeWord(text) {
   869→    const t = text.toLowerCase().trim();
   870→    // Fuzzy patterns: "hey chill", "hey chil", "a chill", "hay chill", etc.
   871→    return /\b(hey|hay|a)\s+chil{1,2}\b/.test(t);
   872→}
   873→
   874→function initWakeRecognition() {
   875→    if (!SpeechRecognition) return;
   876→
   877→    wakeRecognition = new SpeechRecognition();
   878→    wakeRecognition.continuous      = true;
   879→    wakeRecognition.interimResults  = true;
   880→    wakeRecognition.lang            = getRecognitionLang();
   881→    wakeRecognition.maxAlternatives = 3;
   882→
   883→    wakeRecognition.onresult = (event) => {
   884→        for (let i = event.resultIndex; i < event.results.length; i++) {
   885→            const result = event.results[i];
   886→            for (let j = 0; j < result.length; j++) {
   887→                if (matchesWakeWord(result[j].transcript)) {
   888→                    handleWakeWordDetected();
   889→                    return;
   890→                }
   891→            }
   892→        }
   893→    };
   894→
   895→    wakeRecognition.onerror = (event) => {
   896→        if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
   897→            console.warn('Wake word mic denied:', event.error);
   898→            wakeWordListening = false;
   899→            updateWakeDot();
   900→            return;
   901→        }
   902→        // Transient error — will be restarted by onend handler
   903→    };
   904→
   905→    wakeRecognition.onend = () => {
   906→        wakeWordListening = false;
   907→        updateWakeDot();
   908→        // Auto-restart when not in an active mode
   909→        if (handsFreeEnabled && !isListening && !isBrainstormRecording && !isBrainstormProcessing) {
   910→            setTimeout(startWakeWordListening, 300);
   911→        }
   912→    };
   913→}
   914→
   915→function startWakeWordListening() {
   916→    if (!SpeechRecognition || !handsFreeEnabled) return;
   917→    if (isListening || isBrainstormRecording || isBrainstormProcessing) return;
   918→    if (wakeWordListening) return;
   919→
   920→    if (!wakeRecognition) initWakeRecognition();
   921→
   922→    try {
   923→        wakeRecognition.start();
   924→        wakeWordListening = true;
   925→        updateWakeDot();
   926→    } catch (e) {
   927→        console.warn('Could not start wake recognition:', e);
   928→        wakeWordListening = false;
   929→        // Re-init and try once more next cycle
   930→        initWakeRecognition();
   931→    }
   932→}
   933→
   934→function stopWakeWordListening() {
   935→    wakeWordListening = false;
   936→    updateWakeDot();
   937→    if (wakeRecognition) {
   938→        try { wakeRecognition.stop(); } catch (_) {}
   939→    }
   940→}
   941→
   942→function handleWakeWordDetected() {
   943→    stopWakeWordListening();
   944→    if (!isListening && !isBrainstormRecording && !isBrainstormProcessing && !isReplaying) {
   945→        haptic(50);
   946→        startQuickMode();
   947→    }
   948→}
   949→
   950→function updateWakeDot() {
   951→    if (!wakeDot) return;
   952→    wakeDot.hidden = !(handsFreeEnabled && wakeWordListening);
   953→}
   954→
   955→function setHandsFree(enabled) {
   956→    handsFreeEnabled = enabled;
   957→    localStorage.setItem('handsFreeEnabled', enabled ? '1' : '0');
   958→    if (enabled) {
   959→        startWakeWordListening();
   960→    } else {
   961→        stopWakeWordListening();
   962→    }
   963→    updateWakeDot();
   964→}
