   966→/* ===================================================
   967→   BRAINSTORM MODE — WebSocket + PCM16 audio streaming
   968→   =================================================== */
   969→
   970→function getWebSocketUrl() {
   971→    const backendUrl = localStorage.getItem('brainwaveBackendUrl') || '';
   972→    if (backendUrl) {
   973→        try {
   974→            const url    = new URL(backendUrl);
   975→            const wsProto = url.protocol === 'https:' ? 'wss:' : 'ws:';
   976→            return `${wsProto}//${url.host}/api/v1/ws`;
   977→        } catch (_) { /* fall through to default */ }
   978→    }
   979→    const proto = window.location.protocol === 'https:' ? 'wss' : 'ws';
   980→    return `${proto}://${window.location.host}/api/v1/ws`;
   981→}
   982→
   983→function updateConnectionStatus(status) {
   984→    connectionStatus.className = 'ws-dot';
   985→    switch (status) {
   986→        case 'connected':
   987→            connectionStatus.classList.add('connected');
   988→            connectionStatus.title = 'Connected';
   989→            break;
   990→        case 'connecting':
   991→            connectionStatus.classList.add('connecting');
   992→            connectionStatus.title = 'Connecting…';
   993→            break;
   994→        case 'idle':
   995→            connectionStatus.classList.add('idle');
   996→            connectionStatus.title = 'Ready';
   997→            break;
   998→        default:
   999→            connectionStatus.title = 'Disconnected';
  1000→    }
  1001→}
  1002→
  1003→function initializeWebSocket() {
  1004→    ws = new WebSocket(getWebSocketUrl());
  1005→
  1006→    ws.onopen = () => {
  1007→        wsConnected = true;
  1008→        updateConnectionStatus('idle');
  1009→        if (autoStart && !isBrainstormRecording && !isAutoStarted) {
  1010→            isAutoStarted = true;
  1011→            startBrainstormRecording();
  1012→        }
  1013→    };
  1014→
  1015→    ws.onerror = (error) => {
  1016→        console.error('WebSocket error:', error);
  1017→        updateConnectionStatus('disconnected');
  1018→    };
  1019→
  1020→    ws.onmessage = (event) => {
  1021→        const data = JSON.parse(event.data);
  1022→        switch (data.type) {
  1023→            case 'status':
  1024→                updateConnectionStatus(data.status);
  1025→                if (data.status === 'idle') {
  1026→                    stopTimer();
  1027→                    if (_awaitingBrainstormResult) {
  1028→                        _awaitingBrainstormResult = false;
  1029→                        isBrainstormProcessing    = false;
  1030→                        quickBtn.disabled         = false;
  1031→                        brainstormBtn.disabled    = false;
  1032→                        micHint.textContent       = '';
  1033→                        micHint.classList.remove('active', 'brainstorm-active', 'processing');
  1034→                        hideLiveTranscript();
  1035→                        updateReplayButtonState();
  1036→                        const finalText = brainstormTranscript.trim();
  1037→                        brainstormTranscript = '';
  1038→                        if (finalText) {
  1039→                            showCardStack(finalText, lastRecordingDurationMs);
  1040→                        }
  1041→                        // Resume hands-free after brainstorm completes
  1042→                        if (handsFreeEnabled) {
  1043→                            setTimeout(startWakeWordListening, 400);
  1044→                        }
  1045→                    }
  1046→                }
  1047→                break;
  1048→
  1049→            case 'text':
  1050→                if (data.isNewResponse) {
  1051→                    brainstormTranscript = data.content;
  1052→                } else {
  1053→                    brainstormTranscript += data.content;
  1054→                }
  1055→                if (isBrainstormProcessing) {
  1056→                    updateLiveText(brainstormTranscript);
  1057→                }
  1058→                break;
  1059→
  1060→            case 'error':
  1061→                alert(data.content);
  1062→                updateConnectionStatus('idle');
  1063→                _awaitingBrainstormResult = false;
  1064→                isBrainstormProcessing    = false;
  1065→                quickBtn.disabled         = false;
  1066→                brainstormBtn.disabled    = false;
  1067→                micHint.textContent       = '';
  1068→                micHint.classList.remove('active', 'brainstorm-active', 'processing');
  1069→                hideLiveTranscript();
  1070→                brainstormTranscript = '';
  1071→                updateReplayButtonState();
  1072→                if (handsFreeEnabled) {
  1073→                    setTimeout(startWakeWordListening, 400);
  1074→                }
  1075→                break;
  1076→        }
  1077→    };
  1078→
  1079→    ws.onclose = () => {
  1080→        wsConnected            = false;
  1081→        isBrainstormRecording  = false;
  1082→        isStopping             = false;
  1083→        updateConnectionStatus('disconnected');
  1084→        brainstormBtn.classList.remove('recording');
  1085→        brainstormRing.classList.remove('recording');
  1086→        brainstormBtn.setAttribute('aria-pressed', 'false');
  1087→        // Reconnect automatically
  1088→        setTimeout(initializeWebSocket, 1000);
  1089→    };
  1090→}
