  1092→/* ===== Audio processing ===== */
  1093→function createAudioProcessor() {
  1094→    processor = audioContext.createScriptProcessor(4096, 1, 1);
  1095→    processor.onaudioprocess = async (e) => {
  1096→        if (!isBrainstormRecording && !isStopping) return;
  1097→
  1098→        const inputData = e.inputBuffer.getChannelData(0);
  1099→        const pcmData   = new Int16Array(inputData.length);
  1100→        for (let i = 0; i < inputData.length; i++) {
  1101→            pcmData[i] = Math.max(-32768, Math.min(32767, Math.floor(inputData[i] * 32767)));
  1102→        }
  1103→
  1104→        const combined = new Int16Array(audioBuffer.length + pcmData.length);
  1105→        combined.set(audioBuffer);
  1106→        combined.set(pcmData, audioBuffer.length);
  1107→        audioBuffer = combined;
  1108→
  1109→        if (audioBuffer.length >= 24000) {
  1110→            const sendBuffer = audioBuffer.slice(0, 24000);
  1111→            audioBuffer      = audioBuffer.slice(24000);
  1112→
  1113→            if (ws.readyState === WebSocket.OPEN) {
  1114→                ws.send(sendBuffer.buffer);
  1115→
  1116→                if (storageAvailable && currentSessionId && sessionStartTime) {
  1117→                    const deltaMs = performance.now() - sessionStartTime;
  1118→                    await appendChunk(currentSessionId, {
  1119→                        seq: chunkSeq++, deltaMs,
  1120→                        kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
  1121→                    });
  1122→                }
  1123→            }
  1124→        }
  1125→    };
  1126→    return processor;
  1127→}
  1128→
  1129→async function initAudio(audioStream) {
  1130→    if (audioContext && audioContext.state !== 'closed') {
  1131→        try { await audioContext.close(); } catch (_) {}
  1132→    }
  1133→    audioContext = new (window.AudioContext || window.webkitAudioContext)();
  1134→    source       = audioContext.createMediaStreamSource(audioStream);
  1135→    processor    = createAudioProcessor();
  1136→    source.connect(processor);
  1137→    processor.connect(audioContext.destination);
  1138→    if (audioContext.state === 'suspended') await audioContext.resume();
  1139→}
  1140→
  1141→function cleanupAudioResources() {
  1142→    if (stream) {
  1143→        stream.getTracks().forEach(t => t.stop());
  1144→        stream = null;
  1145→    }
  1146→    if (audioContext && audioContext.state !== 'closed') {
  1147→        audioContext.close().catch(() => {});
  1148→        audioContext = null;
  1149→    }
  1150→    source            = null;
  1151→    processor         = null;
  1152→    streamInitialized = false;
  1153→}
  1154→
  1155→async function startBrainstormRecording() {
  1156→    if (isBrainstormRecording || isListening || isBrainstormProcessing || isReplaying) return;
  1157→
  1158→    if (!ws || ws.readyState !== WebSocket.OPEN) {
  1159→        alert('WebSocket is not connected. Please wait or check the backend URL in Settings.');
  1160→        return;
  1161→    }
  1162→
  1163→    // Pause wake word listening while brainstorm is active
  1164→    if (wakeWordListening) stopWakeWordListening();
  1165→
  1166→    // Stop any active local playback
  1167→    if (isPlayingBack) stopLocalPlayback();
  1168→
  1169→    try {
  1170→        brainstormTranscript = '';
  1171→        hideTranscriptBar();
  1172→        hideCardStackInstant();
  1173→
  1174→        // Re-use existing stream if still alive, else reinit
  1175→        let streamActive = false;
  1176→        try {
  1177→            streamActive = streamInitialized && stream && stream.active &&
  1178→                           stream.getTracks().every(t => t.readyState === 'live');
  1179→        } catch (_) { streamActive = false; }
  1180→
  1181→        if (!streamActive) {
  1182→            cleanupAudioResources();
  1183→            stream = await navigator.mediaDevices.getUserMedia({
  1184→                audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
  1185→            });
  1186→            streamInitialized = true;
  1187→        }
  1188→
  1189→        if (!audioContext || audioContext.state === 'closed') {
  1190→            await initAudio(stream);
  1191→        } else if (audioContext.state === 'suspended') {
  1192→            await audioContext.resume();
  1193→        }
  1194→
  1195→        isBrainstormRecording = true;
  1196→        if (storageAvailable) await createSession();
  1197→
  1198→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
  1199→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
  1200→
  1201→        startTimer();
  1202→        brainstormBtn.classList.add('recording');
  1203→        brainstormRing.classList.add('recording');
  1204→        brainstormBtn.setAttribute('aria-pressed', 'true');
  1205→        quickBtn.disabled    = true;
  1206→        replayButton.disabled = true;
  1207→        micHint.textContent  = 'Recording… tap Brainstorm to stop';
  1208→        micHint.classList.add('active', 'brainstorm-active');
  1209→        micHint.classList.remove('processing');
  1210→        showLiveTranscript('', 'brainstorm');
  1211→
  1212→    } catch (error) {
  1213→        console.error('Error starting Brainstorm:', error);
  1214→        isBrainstormRecording = false;
  1215→        alert('Error accessing microphone: ' + error.message);
  1216→    }
  1217→}
  1218→
  1219→async function stopBrainstormRecording() {
  1220→    if (!isBrainstormRecording) return;
  1221→
  1222→    isStopping               = true;
  1223→    isBrainstormRecording    = false;
  1224→    const durationMs         = sessionStartTime ? performance.now() - sessionStartTime : 0;
  1225→    lastRecordingDurationMs  = durationMs;
  1226→
  1227→    stopTimer();
  1228→    brainstormBtn.classList.remove('recording');
  1229→    brainstormRing.classList.remove('recording');
  1230→    brainstormBtn.setAttribute('aria-pressed', 'false');
  1231→    brainstormBtn.disabled = true; // keep disabled until WS idle
  1232→
  1233→    micHint.textContent = 'Processing…';
  1234→    micHint.classList.remove('brainstorm-active');
  1235→    micHint.classList.add('processing');
  1236→
  1237→    // Allow any in-flight onaudioprocess callbacks to complete
  1238→    await new Promise(resolve => setTimeout(resolve, 100));
  1239→
  1240→    // Flush remaining audio buffer
  1241→    if (audioBuffer.length > 0 && ws.readyState === WebSocket.OPEN) {
  1242→        const sendBuffer = audioBuffer.slice();
  1243→        ws.send(sendBuffer.buffer);
  1244→        if (storageAvailable && currentSessionId && sessionStartTime) {
  1245→            const deltaMs = performance.now() - sessionStartTime;
  1246→            await appendChunk(currentSessionId, {
  1247→                seq: chunkSeq++, deltaMs,
  1248→                kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
  1249→            });
  1250→        }
  1251→        audioBuffer = new Int16Array(0);
  1252→    }
  1253→
  1254→    isStopping = false;
  1255→
  1256→    // Small delay to ensure all audio sent before stop signal
  1257→    await new Promise(resolve => setTimeout(resolve, 500));
  1258→    ws.send(JSON.stringify({ type: 'stop_recording' }));
  1259→
  1260→    if (storageAvailable && currentSessionId) {
  1261→        await completeSession(currentSessionId, durationMs);
  1262→        currentSessionId  = null;
  1263→        sessionStartTime  = null;
  1264→        chunkSeq          = 0;
  1265→        invalidateReplayBuffer();
  1266→    }
  1267→
  1268→    // Switch to processing state — WS idle handler will finish the flow
  1269→    isBrainstormProcessing    = true;
  1270→    _awaitingBrainstormResult = true;
  1271→    liveText.textContent      = 'Processing…';
  1272→    liveText.classList.remove('has-text');
  1273→}
  1274→
  1275→brainstormBtn.addEventListener('click', () => {
  1276→    haptic(50);
  1277→    if (isBrainstormRecording) {
  1278→        stopBrainstormRecording();
