  1284→/* ===================================================
  1285→   REPLAY — local audio playback of stored recording
  1286→   =================================================== */
  1287→
  1288→/** Assemble PCM16 chunks from IndexedDB into a Web Audio AudioBuffer. */
  1289→async function buildReplayAudioBuffer() {
  1290→    const session = await getLatestCompletedSession();
  1291→    if (!session) return null;
  1292→    const chunks      = await getSessionChunks(session.id);
  1293→    const audioChunks = chunks.filter(c => c.kind === 'audio' && c.payload);
  1294→    if (audioChunks.length === 0) return null;
  1295→
  1296→    const SAMPLE_RATE = session.sampleRate || 24000;
  1297→    let totalSamples  = 0;
  1298→    for (const chunk of audioChunks) totalSamples += new Int16Array(chunk.payload).length;
  1299→
  1300→    // AudioBuffer constructor (Chrome 55+, FF 53+, Safari 14.1+)
  1301→    const audioBuf    = new AudioBuffer({ numberOfChannels: 1, length: totalSamples, sampleRate: SAMPLE_RATE });
  1302→    const channelData = audioBuf.getChannelData(0);
  1303→    let offset = 0;
  1304→    for (const chunk of audioChunks) {
  1305→        const pcm = new Int16Array(chunk.payload);
  1306→        for (let i = 0; i < pcm.length; i++) channelData[offset++] = pcm[i] / 32768;
  1307→    }
  1308→    return audioBuf;
  1309→}
  1310→
  1311→function _replaySetPlayIcon(playing) {
  1312→    const playIcon  = replayButton.querySelector('.replay-icon-play');
  1313→    const pauseIcon = replayButton.querySelector('.replay-icon-pause');
  1314→    if (playIcon)  playIcon.hidden  = playing;
  1315→    if (pauseIcon) pauseIcon.hidden = !playing;
  1316→}
  1317→
  1318→function _replayTickProgress() {
  1319→    if (!isPlayingBack || !replayAudioCtx) return;
  1320→    const elapsed = (replayAudioCtx.currentTime - replayStartedAt) + replayPauseOffset;
  1321→    const pct = replayDuration > 0 ? Math.min(elapsed / replayDuration, 1) : 0;
  1322→    if (replayProgressFill) replayProgressFill.style.width = (pct * 100).toFixed(2) + '%';
  1323→    if (pct < 1) replayRAF = requestAnimationFrame(_replayTickProgress);
  1324→}
  1325→
  1326→async function _ensureReplayAudioCtx() {
  1327→    if (!replayAudioCtx || replayAudioCtx.state === 'closed') {
  1328→        replayAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  1329→    }
  1330→    if (replayAudioCtx.state === 'suspended') await replayAudioCtx.resume();
  1331→}
  1332→
  1333→function _replayOnEnded() {
  1334→    isPlayingBack     = false;
  1335→    isReplaying       = false;
  1336→    replayAudioSource = null;
  1337→    replayPauseOffset = 0;
  1338→    replayStartedAt   = 0;
  1339→    cancelAnimationFrame(replayRAF);
  1340→    if (replayProgressFill) replayProgressFill.style.width = '0%';
  1341→    _replaySetPlayIcon(false);
  1342→    stopButton.hidden = true;
  1343→    replayButton.classList.remove('replay-playing');
  1344→    if (replayProgressWrap) replayProgressWrap.hidden = true;
  1345→    updateReplayButtonState();
  1346→}
  1347→
  1348→async function toggleLocalPlayback() {
  1349→    if (isBrainstormRecording || isListening || isBrainstormProcessing) return;
  1350→
  1351→    if (isPlayingBack) {
  1352→        // Pause: record elapsed time and stop source
  1353→        replayPauseOffset += replayAudioCtx.currentTime - replayStartedAt;
  1354→        if (replayAudioSource) {
  1355→            replayAudioSource.onended = null;
  1356→            replayAudioSource.stop();
  1357→            replayAudioSource = null;
  1358→        }
  1359→        cancelAnimationFrame(replayRAF);
  1360→        isPlayingBack = false;
  1361→        isReplaying   = false;
  1362→        _replaySetPlayIcon(false);
  1363→        replayButton.classList.remove('replay-playing');
  1364→        replayButton.title = 'Resume playback';
  1365→        return;
  1366→    }
  1367→
  1368→    // Load buffer on first play (or after stop cleared it)
  1369→    if (!replayAudioBuf) {
  1370→        replayButton.disabled = true;
  1371→        replayButton.title    = 'Loading…';
  1372→        try {
  1373→            replayAudioBuf = await buildReplayAudioBuffer();
  1374→        } catch (e) {
  1375→            console.error('Failed to build audio buffer:', e);
  1376→            replayButton.disabled = false;
  1377→            updateReplayButtonState();
  1378→            return;
  1379→        }
  1380→        if (!replayAudioBuf) {
  1381→            updateReplayButtonState();
  1382→            return;
  1383→        }
  1384→        replayDuration = replayAudioBuf.duration;
  1385→    }
  1386→
  1387→    // Restart from beginning if we've reached the end
  1388→    if (replayPauseOffset >= replayDuration) {
  1389→        replayPauseOffset = 0;
  1390→        if (replayProgressFill) replayProgressFill.style.width = '0%';
  1391→    }
  1392→
  1393→    try {
  1394→        await _ensureReplayAudioCtx();
  1395→        const src = replayAudioCtx.createBufferSource();
  1396→        src.buffer = replayAudioBuf;
  1397→        src.connect(replayAudioCtx.destination);
  1398→        src.onended = _replayOnEnded;
  1399→
  1400→        replayAudioSource = src;
  1401→        replayStartedAt   = replayAudioCtx.currentTime;
  1402→        isPlayingBack     = true;
  1403→        isReplaying       = true;
  1404→
  1405→        src.start(0, replayPauseOffset);
  1406→
  1407→        _replaySetPlayIcon(true);
  1408→        replayButton.classList.add('replay-playing');
  1409→        replayButton.disabled = false;
  1410→        replayButton.title    = 'Pause playback';
  1411→        stopButton.hidden     = false;
  1412→        if (replayProgressWrap) replayProgressWrap.hidden = false;
  1413→        replayRAF = requestAnimationFrame(_replayTickProgress);
  1414→    } catch (e) {
  1415→        console.error('Playback error:', e);
  1416→        isPlayingBack = false;
  1417→        isReplaying   = false;
  1418→        updateReplayButtonState();
  1419→    }
  1420→}
  1421→
  1422→function stopLocalPlayback() {
  1423→    if (replayAudioSource) {
  1424→        replayAudioSource.onended = null;
  1425→        try { replayAudioSource.stop(); } catch (_) {}
  1426→        replayAudioSource = null;
  1427→    }
  1428→    cancelAnimationFrame(replayRAF);
  1429→    isPlayingBack     = false;
  1430→    isReplaying       = false;
  1431→    replayPauseOffset = 0;  // reset to start; buffer stays cached for fast re-play
  1432→    if (replayProgressFill) replayProgressFill.style.width = '0%';
  1433→    _replaySetPlayIcon(false);
  1434→    if (replayProgressWrap) replayProgressWrap.hidden = true;
  1435→    stopButton.hidden = true;
  1436→    replayButton.classList.remove('replay-playing');
  1437→    replayButton.title = 'Play last recording';
  1438→    updateReplayButtonState();
  1439→}
  1440→
  1441→/** Called when a new recording is completed — invalidate the cached buffer. */
  1442→function invalidateReplayBuffer() {
  1443→    replayAudioBuf = null;
  1444→    if (!isPlayingBack) {
  1445→        replayPauseOffset = 0;
  1446→        if (replayProgressFill) replayProgressFill.style.width = '0%';
  1447→    }
  1448→}
  1449→
  1450→replayButton.onclick = toggleLocalPlayback;
  1451→stopButton.onclick   = stopLocalPlayback;
  1452→
  1453→function updateReplayButtonState() {
  1454→    if (!replayButton) return;
  1455→
  1456→    if (!storageAvailable) {
  1457→        replayButton.disabled = true;
  1458→        replayButton.title    = 'Local storage not available';
  1459→        return;
  1460→    }
  1461→    if (isBrainstormRecording || isListening || isBrainstormProcessing) {
  1462→        replayButton.disabled = true;
  1463→        stopButton.hidden     = true;
  1464→        return;
  1465→    }
  1466→    if (isPlayingBack) {
  1467→        replayButton.disabled = false;
  1468→        replayButton.title    = 'Pause playback';
  1469→        return;
  1470→    }
  1471→
  1472→    getLatestCompletedSession().then(session => {
  1473→        if (!isPlayingBack) {
  1474→            replayButton.disabled = !session;
  1475→            if (session) {
  1476→                replayButton.title         = replayPauseOffset > 0 ? 'Resume playback' : 'Play last recording';
  1477→                replayButton.dataset.state = 'available';
  1478→            } else {
  1479→                replayButton.title         = 'No recording to replay';
  1480→                replayButton.dataset.state = '';
  1481→            }
  1482→        }
  1483→    });
  1484→}
