  1486→/* ===================================================
  1487→   INDEXEDDB — stores PCM16 chunks for replay
  1488→   =================================================== */
  1489→
  1490→function createDBStores(event) {
  1491→    const d = event.target.result;
  1492→    if (!d.objectStoreNames.contains('sessions')) {
  1493→        const s = d.createObjectStore('sessions', { keyPath: 'id', autoIncrement: true });
  1494→        s.createIndex('status',    'status',    { unique: false });
  1495→        s.createIndex('createdAt', 'createdAt', { unique: false });
  1496→    }
  1497→    if (!d.objectStoreNames.contains('chunks')) {
  1498→        const c = d.createObjectStore('chunks', { keyPath: 'id', autoIncrement: true });
  1499→        c.createIndex('sessionId', 'sessionId', { unique: false });
  1500→        c.createIndex('seq',       'seq',       { unique: false });
  1501→    }
  1502→}
  1503→
  1504→async function initIndexedDB() {
  1505→    return new Promise((resolve) => {
  1506→        const request = indexedDB.open('brainwave-replay', 1);
  1507→
  1508→        request.onerror = () => {
  1509→            console.warn('IndexedDB not available, replay disabled');
  1510→            storageAvailable = false;
  1511→            resolve(false);
  1512→        };
  1513→
  1514→        request.onsuccess = () => {
  1515→            db = request.result;
  1516→            if (!db.objectStoreNames.contains('sessions') || !db.objectStoreNames.contains('chunks')) {
  1517→                db.close();
  1518→                const del = indexedDB.deleteDatabase('brainwave-replay');
  1519→                del.onsuccess = () => {
  1520→                    const reopen = indexedDB.open('brainwave-replay', 1);
  1521→                    reopen.onsuccess       = () => { db = reopen.result; storageAvailable = true; updateReplayButtonState(); resolve(true); };
  1522→                    reopen.onerror         = () => { storageAvailable = false; resolve(false); };
  1523→                    reopen.onupgradeneeded = createDBStores;
  1524→                };
  1525→                del.onerror = () => { storageAvailable = false; resolve(false); };
  1526→                return;
  1527→            }
  1528→            storageAvailable = true;
  1529→            updateReplayButtonState();
  1530→            resolve(true);
  1531→        };
  1532→
  1533→        request.onupgradeneeded = createDBStores;
  1534→    });
  1535→}
  1536→
  1537→async function createSession() {
  1538→    if (!db) return null;
  1539→    return new Promise((resolve, reject) => {
  1540→        const tx    = db.transaction(['sessions'], 'readwrite');
  1541→        const store = tx.objectStore('sessions');
  1542→        const req   = store.add({ createdAt: new Date(), status: 'recording', sampleRate: 24000, channelCount: 1, durationMs: 0 });
  1543→        req.onsuccess = () => {
  1544→            currentSessionId  = req.result;
  1545→            sessionStartTime  = performance.now();
  1546→            chunkSeq          = 0;
  1547→            appendChunk(currentSessionId, { seq: 0, deltaMs: 0, kind: 'start', payload: null, byteLength: 0 });
  1548→            resolve(currentSessionId);
  1549→        };
  1550→        req.onerror = () => reject(req.error);
  1551→    });
  1552→}
  1553→
  1554→async function appendChunk(sessionId, chunk) {
  1555→    if (!db || !sessionId) return;
  1556→    return new Promise((resolve) => {
  1557→        const tx    = db.transaction(['chunks'], 'readwrite');
  1558→        const store = tx.objectStore('chunks');
  1559→        const req   = store.add({ sessionId, seq: chunk.seq, deltaMs: chunk.deltaMs, kind: chunk.kind, payload: chunk.payload, byteLength: chunk.byteLength });
  1560→        req.onsuccess = () => resolve();
  1561→        req.onerror   = () => resolve(); // don't fail recording on storage error
  1562→    });
  1563→}
  1564→
  1565→async function completeSession(sessionId, durationMs) {
  1566→    if (!db || !sessionId) return;
  1567→    return new Promise((resolve) => {
  1568→        const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1569→        const sessionsStore = tx.objectStore('sessions');
  1570→        const chunksStore   = tx.objectStore('chunks');
  1571→        const req           = sessionsStore.get(sessionId);
  1572→        req.onsuccess = () => {
  1573→            const sess = req.result;
  1574→            sess.status    = 'completed';
  1575→            sess.durationMs = durationMs;
  1576→            sessionsStore.put(sess);
  1577→            chunksStore.add({ sessionId, seq: chunkSeq++, deltaMs: durationMs, kind: 'stop', payload: null, byteLength: 0 });
  1578→            enforceQuota({ maxSessions: 5 });
  1579→            resolve();
  1580→        };
  1581→        req.onerror = () => resolve();
  1582→    });
  1583→}
  1584→
  1585→async function enforceQuota({ maxSessions }) {
  1586→    if (!db) return;
  1587→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1588→    const sessionsStore = tx.objectStore('sessions');
  1589→    const sessions      = [];
  1590→    sessionsStore.index('createdAt').openCursor().onsuccess = (event) => {
  1591→        const cursor = event.target.result;
  1592→        if (cursor) { sessions.push(cursor.value); cursor.continue(); }
  1593→        else {
  1594→            sessions.sort((a, b) => a.createdAt - b.createdAt);
  1595→            while (sessions.length > maxSessions) deleteSession(sessions.shift().id);
  1596→        }
  1597→    };
  1598→}
  1599→
  1600→async function deleteSession(sessionId) {
  1601→    if (!db) return;
  1602→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1603→    const sessionsStore = tx.objectStore('sessions');
  1604→    const chunksStore   = tx.objectStore('chunks');
  1605→    chunksStore.index('sessionId').openKeyCursor(IDBKeyRange.only(sessionId)).onsuccess = (event) => {
  1606→        const cursor = event.target.result;
  1607→        if (cursor) { chunksStore.delete(cursor.primaryKey); cursor.continue(); }
  1608→    };
  1609→    sessionsStore.delete(sessionId);
  1610→}
  1611→
  1612→async function getLatestCompletedSession() {
  1613→    if (!db) return null;
  1614→    return new Promise((resolve) => {
  1615→        const tx    = db.transaction(['sessions'], 'readonly');
  1616→        const req   = tx.objectStore('sessions').index('status').getAll('completed');
  1617→        req.onsuccess = () => {
  1618→            const sessions = req.result;
  1619→            if (!sessions.length) { resolve(null); return; }
  1620→            sessions.sort((a, b) => b.createdAt - a.createdAt);
  1621→            resolve(sessions[0]);
  1622→        };
  1623→        req.onerror = () => resolve(null);
  1624→    });
  1625→}
  1626→
  1627→async function getSessionChunks(sessionId) {
  1628→    if (!db || !sessionId) return [];
  1629→    return new Promise((resolve) => {
  1630→        const tx  = db.transaction(['chunks'], 'readonly');
  1631→        const req = tx.objectStore('chunks').index('sessionId').getAll(sessionId);
  1632→        req.onsuccess = () => {
  1633→            const chunks = req.result;
  1634→            chunks.sort((a, b) => a.seq - b.seq);
  1635→            resolve(chunks);
  1636→        };
  1637→        req.onerror = () => resolve([]);
  1638→    });
  1639→}
  1640→
  1641→/* ===== KEYBOARD SHORTCUT ===== */
  1642→document.addEventListener('keydown', (event) => {
  1643→    if (event.code === 'Space') {
  1644→        const el = document.activeElement;
  1645→        if (!el.tagName.match(/INPUT|TEXTAREA|SELECT/) && !el.isContentEditable) {
  1646→            event.preventDefault();
  1647→            if (isListening) {
  1648→                stopQuickMode();
  1649→            } else if (isBrainstormRecording) {
  1650→                stopBrainstormRecording();
  1651→            } else if (!isBrainstormProcessing && !isReplaying) {
  1652→                startQuickMode();
  1653→            }
  1654→        }
  1655→    }
  1656→});
  1657→
  1658→/* ===== INIT ===== */
  1659→document.addEventListener('DOMContentLoaded', async () => {
  1660→    await initIndexedDB();
  1661→
  1662→    if (!SpeechRecognition) {
  1663→        notSupported.hidden = false;
  1664→        quickBtn.disabled   = true;
  1665→        quickBtn.title      = 'Speech recognition not supported in this browser';
  1666→    } else {
  1667→        initRecognition();
